command:
const cena = canvas.scene;
if (!cena) {
  ui.notifications.warn("Nenhuma cena ativa.");
  return;
}
if (!game.user.isGM) {
  ui.notifications.warn("Apenas o mestre pode alternar as luzes da cena.");
  return;
}

const luzes = cena.lights;
if (!luzes.size) {
  ui.notifications.info("Esta cena não tem nenhuma luz.");
  return;
}

const algumaAcesa = luzes.some((luz) => !luz.hidden);
await cena.updateEmbeddedDocuments("AmbientLight", luzes.map((luz) => ({ _id: luz.id, hidden: algumaAcesa })));
ui.notifications.info(algumaAcesa ? "Todas as luzes da cena foram apagadas." : "Todas as luzes da cena foram acesas.");
